/**
 * 轮次控制：注册 /cancel-turn 内核命令。
 *
 * 与 `src/index.ts` 一一对应（tsconfig 链路暂缺编译器，lib 为手写等价 ESM；
 * src 保留类型参考，两处改动必须同步）。
 *
 * ## 为什么存在
 *
 * stdio SDK 协议（dsh-sdk-jsonrpc-server 的 handleRequest 白名单）在
 * dsh 0.2.2-rc.1 上没有 `session/cancel` 方法——发它必回 -32603。但命令
 * 系统（`commands` 服务）的处理器直接拿得到 agent 对象，而 dsh-agent-loop
 * 的 `agent.cancel(cause)` 会 `phase.abort.abort(cause)` 中断本轮——
 * 这就是 stdio 通道上唯一的轮内取消通道。
 *
 * ## 谁在用
 *
 * Flutter 外壳（空谷 Ondra）的 `StdioDshTransport.stop()`：用户点「停止」
 * 或在生成中插话（busyPolicy=steer）时，先发 `session/query` 执行
 * `/cancel-turn`，内核中断当前轮并以 aborted 的 turn/end 收尾；连接与
 * 进程保持，下一句在同一会话里继续。cancel 失败时外壳退回旧语义
 * （断开连接重启内核），本插件不承担兼容职责。
 */

/** @param {import('@ntars/cordis').Context} ctx */
export function apply(ctx) {
	ctx.inject(['commands'], (commandCtx) => {
		commandCtx.commands.register({
			definitionId: '@ondra/cordis-plugin-ondra-turn-control',
			name: 'cancel-turn',
			description: '中断当前正在生成的轮次（保留会话与连接）',
			input: { hint: '' },
			handler: ({ agent, rawInput }) => {
				if (rawInput.trim() !== '') {
					return { kind: 'error', text: '/cancel-turn 不接受参数' };
				}
				const phase = agent?.phase;
				if (phase?.kind === 'idle') {
					return { kind: 'success', text: '当前没有正在生成的轮次' };
				}
				// cause 必须是 CancelCause 联合的结构化对象（agent-loop 的
            // abortedCancelCause 对 cause.kind 做穷举 switch，传 Error 会在
            // assertNever 处抛异常、abort 根本不执行）；keepInbox 与官方
            // sessionController.cancel 的语义一致（保留排队消息）。
            agent.cancel({ kind: 'user' }, { keepInbox: true });
				return { kind: 'success', text: '已中断当前轮次' };
			},
		});
	});
}
